import React, { useEffect, useState } from "react";
import axios from "axios";

export default function DepositForm({ token, onCancel }) {
  const [amount, setAmount] = useState("");
  const [method, setMethod] = useState("bKash");
  const [senderNumber, setSenderNumber] = useState("");
  const [transactionId, setTransactionId] = useState("");
  const [message, setMessage] = useState("");
  const [paymentNumbers, setPaymentNumbers] = useState({});

  // ✅ Fetch payment numbers on load
  useEffect(() => {
    if (!token) return;

    axios
      .get("http://localhost:8080/api/payment-config", {
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((res) => {
        const numbers = {};
        res.data.forEach((config) => {
          numbers[config.method] = config.number;
        });
        setPaymentNumbers(numbers);
      })
      .catch((err) => {
        console.error("Error fetching payment numbers:", err);
        setMessage("❌ Failed to load payment numbers");
      });
  }, [token]);

  // ✅ Submit deposit request
  const handleSubmit = async (e) => {
    e.preventDefault();

    const payload = {
      amount: parseFloat(amount),
      method,
      senderNumber,
      transactionId,
    };

    try {
      const res = await fetch("http://localhost:8080/api/deposit/request", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      if (!res.ok) throw new Error("Deposit failed");

      setMessage("✅ Deposit request sent successfully!");
      setAmount("");
      setSenderNumber("");
      setTransactionId("");
    } catch (err) {
      console.error("Deposit error:", err);
      setMessage("❌ Deposit failed");
    }
  };

  return (
    <div className="max-w-md mx-auto mt-10 p-6 bg-white rounded-xl shadow-lg border border-gray-100">
      <h2 className="text-2xl font-bold text-gray-800 mb-6 text-center">
        💰 Deposit Form
      </h2>

      {/* Message */}
      {message && (
        <div
          className={`mb-4 px-4 py-3 rounded text-sm font-medium ${
            message.startsWith("✅")
              ? "bg-green-100 text-green-700"
              : "bg-red-100 text-red-700"
          }`}
        >
          {message}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-5">
        {/* Amount */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Amount
          </label>
          <input
            type="number"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            required
            min="1"
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring focus:ring-indigo-200"
          />
        </div>

        {/* Payment Method */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Payment Method
          </label>
          <select
            value={method}
            onChange={(e) => setMethod(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring focus:ring-indigo-200"
          >
            <option value="bKash">bKash</option>
            <option value="Nagad">Nagad</option>
            <option value="Rocket">Rocket</option>
          </select>
        </div>

        {/* Show Payment Number from Backend */}
        {paymentNumbers[method] && (
          <div className="p-3 bg-gray-50 border border-gray-200 rounded-lg text-center text-sm text-gray-800">
            Send your payment to:{" "}
            <span className="font-semibold">{paymentNumbers[method]}</span>
          </div>
        )}

        {/* Sender Number */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Sender Number
          </label>
          <input
            type="text"
            value={senderNumber}
            onChange={(e) => setSenderNumber(e.target.value)}
            required
            placeholder="Your mobile number"
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring focus:ring-indigo-200"
          />
        </div>

        {/* Transaction ID */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Transaction ID
          </label>
          <input
            type="text"
            value={transactionId}
            onChange={(e) => setTransactionId(e.target.value)}
            required
            placeholder="Enter transaction ID"
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring focus:ring-indigo-200"
          />
        </div>

        {/* Buttons */}
        <div className="flex justify-between items-center pt-4">
          <button
            type="submit"
            className="bg-green-600 hover:bg-green-700 text-white font-medium py-2 px-4 rounded-lg shadow"
          >
            ✅ Submit
          </button>
          <button
            type="button"
            onClick={onCancel}
            className="bg-gray-500 hover:bg-gray-600 text-white font-medium py-2 px-4 rounded-lg shadow"
          >
            ⬅ Back
          </button>
        </div>
      </form>
    </div>
  );
}
